def rob(nums: List[int]) -> int:
    if len(nums) == 1:
        return nums[0]

    def rob_linear(arr):
        if not arr:
            return 0
        if len(arr) == 1:
            return arr[0]
        n = len(arr)
        max_val = 0
        for mask in range(1 << n):
            valid = True
            for i in range(n - 1):
                if (mask & (1 << i)) and (mask & (1 << (i + 1))):
                    valid = False
                    break
            if valid:
                current_sum = sum(arr[i] for i in range(n) if (mask & (1 << i)))
                if current_sum > max_val:
                    max_val = current_sum
        return max_val

    return max(rob_linear(nums[:-1]), rob_linear(nums[1:]))

