class Solution:
    def rob(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]
        if len(nums) == 2:
            return max(nums[0], nums[1])

        def rob_linear(houses: List[int]) -> int:
            prev_two = 0
            prev_one = 0
            for amount in houses:
                current = max(prev_one, prev_two + amount)
                prev_two = prev_one
                prev_one = current
            return prev_one

        return max(rob_linear(nums[:-1]), rob_linear(nums[1:]))

